//
//  TeslaWheel.swift
//  Powerwall-TV
//
//  Which wheels a car wears: Fleet `vehicle_config.wheel_type` mapped the way the Tesla app does it
//  (VehicleOptions.gd in the Android app's asset pack), with caps or covers on or off, and a standard
//  wheel for each model when Fleet has not said. VehicleWheels.swift mounts the result.
//

import Foundation

