    /// WheelTypeToCapsOverrideMap: when the caps state equals `whenCapsOn`, Tesla draws `asset` instead.
    var capsSwap: (whenCapsOn: Bool, asset: String)? {
        switch self {
        case .gemini: return (false, "Wheel_Gemini_No_Caps")
        case .pinwheelRefresh: return (false, "Wheel_Pinwheel_No_Cap")
        case .apollo19MetallicShadow: return (false, "Wheel_Apollo")
        case .cardenio: return (false, "Wheel_Cardenio_No_Caps")
        case .cybertruckBase18: return (false, "Wheel_Cybertruck_RWD_No_Cap")
        case .cybertruckBase20: return (false, "Wheel_Cybertruck_Standard_No_Cap")
        case .cybertruckPremium: return (false, "Wheel_Cybertruck_Premium_No_Cap")
        case .glider: return (false, "Wheel_Glider_No_Caps")
        case .helix19: return (false, "Wheel_Helix_19_No_Caps")
        case .wishbone19: return (true, "Wheel_Wishbone_20")
        case .wishbone20: return (false, "Wheel_Wishbone_19")
        case .d5018: return (false, "Wheel_D50_No_Caps")
        case .e4118: return (false, "Wheel_E41_NoCaps")
        case .crossflow19: return (false, "Wheel_GeminiDark_No_Caps")
        case .standard19: return (false, "Wheel_Standard_No_Caps")
        case .halo22: return (false, "Wheel_Halo_No_Caps")
        case .riptide20: return (false, "Wheel_Riptide_No_Caps")
        case .cypress21: return (true, "Wheel_Cypress")
        case .arachnidV221: return (false, "Wheel_Arachnid_V2_21_NoCaps")
        case .machinaV219: return (false, "Wheel_Machina2_No_Caps")
        case .uberhelix20: return (false, "Wheel_Uberhelix_No_Caps")
        case .nova19Dark: return (false, "Wheel_D33_Dark_Nova_19_No_Caps")
        default: return nil
        }
    }

    /// Fleet `vehicle_config.wheel_type` (MobileWheelTypeEnumMap), then the car's own names
    /// (GTWWheelTypeEnumMap) where Fleet has none, keyed lowercase with only letters and digits.
    static let fleetNames: [String: TeslaWheel] = [
