        "pinwheelrefresh18": .pinwheelRefresh,
        "pinwheel18capkit": .pinwheelNoCap,
        "pinwheelrefresh18capkit": .pinwheelNoCap,
        "stiletto19": .stilettoSilver,
        "stiletto20": .stilettoSilver,
        "stiletto20darksquare": .stilettoDark,
        "stiletto20darkstaggered": .stilettoDark,
