    /// The usdz Tesla draws for this style with the caps or covers on or off.
    func asset(capsOn: Bool) -> String {
        if let swap = capsSwap, swap.whenCapsOn == capsOn { return swap.asset }
        return asset
    }

    /// Every usdz this style can draw.
    var assets: [String] {
        [asset] + (capsSwap.map { [$0.asset] } ?? [])
    }

    var isCybertruck: Bool {
        switch self {
        case .cybertruckBase18, .cybertruckBase20, .cybertruckPremium: return true
        default: return false
        }
    }

    /// One Fleet name per style that fits `model`, in `allCases` order. Caps-on when that file exists.
    /// Cybertruck wheels stay on the Cybertruck. Generic has none.
    static func demoNames(for model: VehicleModel) -> [String] {
        guard model != .generic else { return [] }
        var seenAssets = Set<String>()
        return allCases.compactMap { wheel in
            guard wheel.isCybertruck == (model == .cybertruck) else { return nil }
            let names = fleetNames.filter { $0.value == wheel }.map(\.key).sorted()
            let preferred = names.first {
                WheelChoice.resolve(wheelType: $0, model: model)?.asset == wheel.asset(capsOn: true)
            } ?? names.first
            guard let preferred,
                  let asset = WheelChoice.resolve(wheelType: preferred, model: model)?.asset,
                  seenAssets.insert(asset).inserted else { return nil }
            return preferred
        }
    }

    /// What a model wears when Fleet has not named a wheel, and what catalogue cars always wear.
    /// Tesla's defaults (`DefaultWheelForVehicleType`) where they fit the body we draw; Highland, Juniper,
    /// Model S and Model X keep the wheels their files were exported with.
    static func standard(for model: VehicleModel) -> TeslaWheel? {
        switch model {
        case .generic: return nil
        case .model3: return .pinwheel
        case .model3Highland: return .glider
        case .modelY: return .gemini
        case .modelYJuniper: return .helixV220
        case .modelS: return .cardenio
        case .modelX: return .cyberstream
        case .cybertruck: return .cybertruckBase20
        }
    }

    /// Tesla's marketing names, which neither of its tables lists.
    static let marketingNames: [String: TeslaWheel] = [
        "photon": .glider,
        "nova": .nova19Dark,
        "crossflow": .crossflow19,
    ]

    /// Lowercase letters and digits only, so "PINWHEEL_18_CAP_KIT" and "Pinwheel18CapKit" match.
    static func normalized(_ name: String) -> String {
        String(name.lowercased().unicodeScalars.filter { CharacterSet.alphanumerics.contains($0) && $0.isASCII }.map(Character.init))
    }

    /// Suffixes that mean the caps or aero covers are off.
    static let capsOffMarks = ["capkit", "nocaps", "nocap", "capsoff", "capoff"]

    /// The style a Fleet name means, and whether it says the caps are off. Exact table names first
    /// (Tesla's CapKit names already point at the caps-off style); then, for a name ending in a caps-off
    /// suffix, the name without it; then the shortest table name that starts with it ("Gemini19" is
    /// Gemini19Square), the longest table name it starts with, and a marketing name. Nil when nothing
    /// matches.
    static func named(_ wheelType: String?) -> (wheel: TeslaWheel, capsOff: Bool)? {
        let key = normalized(wheelType ?? "")
        guard !key.isEmpty else { return nil }
        let mark = capsOffMarks.first { key.hasSuffix($0) && key.count > $0.count }
        if let exact = fleetNames[key] { return (exact, mark != nil) }
        if let mark, let wheel = match(String(key.dropLast(mark.count))) { return (wheel, true) }
        return match(key).map { ($0, false) }
    }

    private static func match(_ key: String) -> TeslaWheel? {
        if let exact = fleetNames[key] { return exact }
        if let longer = fleetNames.keys.filter({ $0.hasPrefix(key) }).min(by: { ($0.count, $0) < ($1.count, $1) }) {
            return fleetNames[longer]
        }
        if let shorter = fleetNames.keys.filter({ key.hasPrefix($0) }).max(by: { ($0.count, $0) < ($1.count, $1) }) {
            return fleetNames[shorter]
        }
        return marketingNames.first { key.hasPrefix($0.key) }?.value
    }
}

/// The wheels one car is drawn with.
struct WheelChoice: Equatable {
    enum Source: String {
        /// From the car's `wheel_type`.
        case fleet
        /// The model's standard wheel: no `wheel_type`, one the tables do not know, or a catalogue car.
        case standard
    }

    let wheel: TeslaWheel
    let capsOn: Bool
    let source: Source

    var asset: String { wheel.asset(capsOn: capsOn) }

    /// Nil for the generic body, which has no wheels of its own. `capsOn` is the Tesla app's
    /// `wheel_caps_on`, which Fleet does not send; a caps-off suffix in the name turns it off.
    /// A Cybertruck only takes Cybertruck wheels, and no other car takes them.
    static func resolve(wheelType: String?, model: VehicleModel, capsOn: Bool = true) -> WheelChoice? {
        guard let standard = TeslaWheel.standard(for: model) else { return nil }
        if let named = TeslaWheel.named(wheelType), named.wheel.isCybertruck == (model == .cybertruck) {
            return WheelChoice(wheel: named.wheel, capsOn: capsOn && !named.capsOff, source: .fleet)
        }
        return WheelChoice(wheel: standard, capsOn: true, source: .standard)
    }

    /// One `-debugPaint` fragment: the raw name, the style, and the usdz.
    static func debugDescription(wheelType: String?, choice: WheelChoice?) -> String {
        let raw = wheelType == "" ? "none in vehicle_config" : PaintDebug.raw(wheelType)
        guard let choice else { return "wheel_type=\(raw) → no wheels" }
        return "wheel_type=\(raw) → \(choice.wheel.rawValue) caps \(choice.capsOn ? "on" : "off") \(choice.asset).usdz (\(choice.source.rawValue))"
    }
}
